WITH e AS (SELECT * FROM effects WHERE zone_id = {zone:Int64} AND (capture_id, actor_id) IN (SELECT capture_id, mob_id FROM bestiary_fights WHERE zone_id = {zone:Int64} AND mob_name = {name:String}) AND duration_ms IS NOT NULL AND capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged')), rl AS (SELECT max(release) AS release FROM captures WHERE capture_id IN (SELECT capture_id FROM e)), n AS (SELECT kind, id, any(name) AS name FROM names WHERE release = (SELECT release FROM rl) AND kind IN ('status', 'spell', 'mob_skill') GROUP BY kind, id) SELECT e.category AS category, e.action_id AS action, any(src.name) AS source_name, e.status_id AS status, any(st.name) AS status_name, count() AS n, countIf(e.named) AS named, topK(1)(intDiv(e.duration_ms + 500, 1000))[1] AS usual_s, min(e.duration_ms) AS lo, max(e.duration_ms) AS hi FROM e LEFT JOIN n st ON st.kind = 'status' AND st.id = e.status_id LEFT JOIN n src ON src.kind = if(e.category = 4, 'spell', 'mob_skill') AND src.id = e.action_id GROUP BY e.category, e.action_id, e.status_id ORDER BY e.category DESC, n DESC
